mapper.select:
select
a.param_id,
a.param_code,
a.param_type,
a.param_name,
a.content,
a.remark
from t_sys_param a
where 1 = 1
 and a.param_id = #{paramId, jdbcType=INTEGER}
 and a.param_code = #{paramCode, jdbcType=VARCHAR}
 and a.param_type = #{paramType, jdbcType=INTEGER}
 and a.param_name = #{paramName, jdbcType=VARCHAR}
 and a.content = #{content, jdbcType=VARCHAR}
 and a.remark = #{remark, jdbcType=VARCHAR}

mapper.update:
update t_sys_param a 
a.content = #{content},

where a.param_code = #{paramCode}
